    );
    // Positional args should be: ref first, then content (Commander definition order)
    const positionalStart = 2; // after "task" and "note"
    expect(argv[positionalStart]).toBe("@task1");
    expect(argv[positionalStart + 1]).toBe("my note");
  });
});

